    "tipe": "pg_sederhana",
    "teksSoal": "Sifat Kemagnetan Benda \n     Tahukah kamu bahwa tidak semua benda dapat ditarik magnet? Feromagnetik adalah benda yang mudah ditarik magnet, paramagnetik adalah benda yang lemah ditarik magnet, dan diamagnetik adalah benda yang sulit ditarik magnet.\n\nDi dalam suatu wadah terdapat 25 benda yang berbeda jenisnya. Ternyata 12 diantaranya termasuk feromagnetik dan 7 lainnya paramagnetik, sedangkan sisanya benda diamagnetik. Setelah itu, benda ditambah sehingga menjadi 9 benda diamagnetik. Berapakah benda diamagnetik yang baru ditambahkan?",
