    "teksSoal": "Pembangkit Listrik Tenaga Air Desa \n     Di suatu desa terdapat tiga kincir air untuk memenuhi kebutuhan listrik: Kincir A (94 watt/hari), Kincir B (82 watt/hari), dan Kincir C (96 watt/hari).\n\nKetiga kincir digunakan selama dua hari. Sisa daya listrik setelah dua hari dicatat: Kincir A sisa 42 watt, Kincir B sisa 13 watt, dan Kincir C sisa 30 watt. Kincir mana saja yang daya listrik terpakainya lebih dari 150 watt? Pilih semua jawaban yang benar!",
    "teks_soal": "Pembangkit Listrik Tenaga Air Desa \n     Di suatu desa terdapat tiga kincir air untuk memenuhi kebutuhan listrik: Kincir A (94 watt/hari), Kincir B (82 watt/hari), dan Kincir C (96 watt/hari).\n\nKetiga kincir digunakan selama dua hari. Sisa daya listrik setelah dua hari dicatat: Kincir A sisa 42 watt, Kincir B sisa 13 watt, dan Kincir C sisa 30 watt. Kincir mana saja yang daya listrik terpakainya lebih dari 150 watt? Pilih semua jawaban yang benar!",
    "soal": "Pembangkit Listrik Tenaga Air Desa \n     Di suatu desa terdapat tiga kincir air untuk memenuhi kebutuhan listrik: Kincir A (94 watt/hari), Kincir B (82 watt/hari), dan Kincir C (96 watt/hari).\n\nKetiga kincir digunakan selama dua hari. Sisa daya listrik setelah dua hari dicatat: Kincir A sisa 42 watt, Kincir B sisa 13 watt, dan Kincir C sisa 30 watt. Kincir mana saja yang daya listrik terpakainya lebih dari 150 watt? Pilih semua jawaban yang benar!",
