    "pembahasan": "- Kincir A: Total daya $= 2 \\times 94 = 188$ watt. Terpakai $= 188 - 42 = 146$ watt ($< 150$ watt). \n     - Kincir B: Total daya $= 2 \\times 82 = 164$ watt. Terpakai $= 164 - 13 = 151$ watt ($> 150$ watt). \n     - Kincir C: Total daya $= 2 \\times 96 = 192$ watt. Terpakai $= 192 - 30 = 162$ watt ($> 150$ watt). \n     Kincir dengan daya terpakai $> 150$ watt adalah Kincir B dan Kincir C."
