    "materi": "Perbandingan dan Konversi Satuan",
    "tipe": "benar_salah",
    "teksSoal": "Bahan dan Proses Pembuatan Keju \n     Proses pembuatan keju sederhana menggunakan bahan-bahan: 2 gelas susu segar (1 gelas = 200 ml, total 400 ml), 4 sendok teh cuka (1 sdt = 5 ml, total 20 ml), dan garam secukupnya.\n\nSetiap 1 resep pembuatan keju membutuhkan garam sebanyak 4 gr. Seseorang akan membuat keju sebanyak 5 kali resep awal dengan persediaan bahan 2.000 ml susu sapi segar, 140 ml cuka, dan 16 gr garam. Tentukan Benar atau Salah untuk setiap pernyataan berikut!",
    "teks_soal": "Bahan dan Proses Pembuatan Keju \n     Proses pembuatan keju sederhana menggunakan bahan-bahan: 2 gelas susu segar (1 gelas = 200 ml, total 400 ml), 4 sendok teh cuka (1 sdt = 5 ml, total 20 ml), dan garam secukupnya.\n\nSetiap 1 resep pembuatan keju membutuhkan garam sebanyak 4 gr. Seseorang akan membuat keju sebanyak 5 kali resep awal dengan persediaan bahan 2.000 ml susu sapi segar, 140 ml cuka, dan 16 gr garam. Tentukan Benar atau Salah untuk setiap pernyataan berikut!",
    "soal": "Bahan dan Proses Pembuatan Keju \n     Proses pembuatan keju sederhana menggunakan bahan-bahan: 2 gelas susu segar (1 gelas = 200 ml, total 400 ml), 4 sendok teh cuka (1 sdt = 5 ml, total 20 ml), dan garam secukupnya.\n\nSetiap 1 resep pembuatan keju membutuhkan garam sebanyak 4 gr. Seseorang akan membuat keju sebanyak 5 kali resep awal dengan persediaan bahan 2.000 ml susu sapi segar, 140 ml cuka, dan 16 gr garam. Tentukan Benar atau Salah untuk setiap pernyataan berikut!",
