    "tipe": "pg_kompleks",
    "teksSoal": "Jadwal Mencuci di Laundry Koin \n     Linda dan Vidya mencuci baju kotor di tempat laundry koin yang sama. Linda pergi ke laundry setiap 8 hari sekali, sedangkan Vidya setiap 6 hari sekali.\n\nPada tanggal 10 Agustus 2024, Linda dan Vidya bertemu di tempat laundry. Kapankah mereka akan bertemu kembali? Pilih semua jawaban benar!",
