    "tipe": "benar_salah",
    "teksSoal": "Pengemasan Keset Kain Perca \n     Tiga jenis keset: Jenis 1 (berat 800 g), Jenis 2 (berat 1.200 g), dan Jenis 3 (berat 1.500 g).\n\nKeset dikemas dalam sebuah kardus berisi dua jenis keset berbeda. Banyak keset pada setiap kardus dimaksimalkan dengan berat total tidak boleh melebihi 10 kg. Berapa banyak keset yang sebaiknya dimasukkan ke dalam kardus? Pilih Benar atau Salah untuk setiap jumlah keset!",
    "teks_soal": "Pengemasan Keset Kain Perca \n     Tiga jenis keset: Jenis 1 (berat 800 g), Jenis 2 (berat 1.200 g), dan Jenis 3 (berat 1.500 g).\n\nKeset dikemas dalam sebuah kardus berisi dua jenis keset berbeda. Banyak keset pada setiap kardus dimaksimalkan dengan berat total tidak boleh melebihi 10 kg. Berapa banyak keset yang sebaiknya dimasukkan ke dalam kardus? Pilih Benar atau Salah untuk setiap jumlah keset!",
    "soal": "Pengemasan Keset Kain Perca \n     Tiga jenis keset: Jenis 1 (berat 800 g), Jenis 2 (berat 1.200 g), dan Jenis 3 (berat 1.500 g).\n\nKeset dikemas dalam sebuah kardus berisi dua jenis keset berbeda. Banyak keset pada setiap kardus dimaksimalkan dengan berat total tidak boleh melebihi 10 kg. Berapa banyak keset yang sebaiknya dimasukkan ke dalam kardus? Pilih Benar atau Salah untuk setiap jumlah keset!",
