    "tipe": "pg_kompleks",
    "teksSoal": "Laporan Screen Time Siska \n     *Screen Time* adalah waktu yang dihabiskan untuk menatap layar perangkat elektronik. Batas *screen time* Siska yang berusia 16 tahun yaitu 2 jam pada hari sekolah dan 2,5 jam pada hari libur.\n\nSiska sudah melewati batas *screen time* yang diperbolehkan. Tentukanlah pengurangan waktu total *screen time* yang dapat dilakukan oleh Siska pada hari sekolah agar tidak melebihi batas 2 jam! Jawaban benar lebih dari satu!",
    "teks_soal": "Laporan Screen Time Siska \n     *Screen Time* adalah waktu yang dihabiskan untuk menatap layar perangkat elektronik. Batas *screen time* Siska yang berusia 16 tahun yaitu 2 jam pada hari sekolah dan 2,5 jam pada hari libur.\n\nSiska sudah melewati batas *screen time* yang diperbolehkan. Tentukanlah pengurangan waktu total *screen time* yang dapat dilakukan oleh Siska pada hari sekolah agar tidak melebihi batas 2 jam! Jawaban benar lebih dari satu!",
