    "tipe": "benar_salah",
    "teksSoal": "Negara dengan Gunung Berapi Aktif di Dunia \n     Penelitian menunjukkan panas bumi gunung berapi dapat menghasilkan energi listrik. Berikut data gunung berapi aktif di dunia dari tahun 1960 sampai 2023:\n\nDengan 9 gunung berapi yang ada di Tonga, negara tersebut menghasilkan paling sedikit 450 Mw listrik. Asumsikan setiap gunung berapi aktif menghasilkan energi listrik rata-rata yang sama. Tentukan Benar atau Salah untuk setiap pernyataan berikut!",
    "teks_soal": "Negara dengan Gunung Berapi Aktif di Dunia \n     Penelitian menunjukkan panas bumi gunung berapi dapat menghasilkan energi listrik. Berikut data gunung berapi aktif di dunia dari tahun 1960 sampai 2023:\n\nDengan 9 gunung berapi yang ada di Tonga, negara tersebut menghasilkan paling sedikit 450 Mw listrik. Asumsikan setiap gunung berapi aktif menghasilkan energi listrik rata-rata yang sama. Tentukan Benar atau Salah untuk setiap pernyataan berikut!",
    "soal": "Negara dengan Gunung Berapi Aktif di Dunia \n     Penelitian menunjukkan panas bumi gunung berapi dapat menghasilkan energi listrik. Berikut data gunung berapi aktif di dunia dari tahun 1960 sampai 2023:\n\nDengan 9 gunung berapi yang ada di Tonga, negara tersebut menghasilkan paling sedikit 450 Mw listrik. Asumsikan setiap gunung berapi aktif menghasilkan energi listrik rata-rata yang sama. Tentukan Benar atau Salah untuk setiap pernyataan berikut!",
