    "teksSoal": "Indonesia sebagai Negara Maritim dan Ancaman Pencemaran Laut \n       Indonesia adalah negara maritim yang sebagian besar wilayahnya terdiri atas lautan. Laut Indonesia menyimpan banyak kekayaan, seperti ikan, rumput laut, dan terumbu karang. Nelayan mencari nafkah dengan menangkap ikan secara tradisional. Namun, akhir-akhir ini, pencemaran laut mulai meningkat akibat limbah dan sampah plastik. Jika hal ini dibiarkan, laut akan rusak dan hasil tangkapan akan menurun. Oleh karena itu, menjaga laut sama pentingnya dengan menjaga hutan dan daratan.  Sayangnya, masih banyak orang yang menutup mata terhadap masalah ini. Padahal, jika laut rusak, masyarakat pesisir akan kehilangan mata pencaharian. Kita tidak boleh hanya berpangku tangan. Semua pihak harus ikut menjaga laut agar tetap lestari.\n\nBerdasarkan teks, dampak yang akan terjadi jika pencemaran laut tidak segera diatasi adalah ...",
