    "tipe": "benar_salah",
    "teksSoal": "Cara Membuat Telur Dadar Sederhana \n        Cara Membuat Telur Dadar Sederhana  Telur dadar sangat cocok dipadukan dengan nasi hangat dan sambal. Rasanya sederhana, tetapi tetap menggugah selera. Berikut adalah cara membuat telur dadar sederhana.   Bahan-bahan:  • 1 butir telur • Sejumput garam • Sedikit merica bubuk • Minyak goreng secukupnya   Langkah-langkah:  • Pecahkan telur ke dalam mangkuk. • Tambahkan garam dan merica, lalu kocok hingga rata. • Panaskan sedikit minyak di atas wajan. • Tuang telur dan masak hingga matang kedua sisinya. • Angkat dan sajikan selagi hangat.  Telur dadar sederhana kini siap dinikmati sebagai pelengkap hidangan. Untuk variasi rasa, Anda bisa menambahkan irisan daun bawang atau keju parut sesuai dengan selera. Selamat mencoba.\n\nBerdasarkan informasi tersebut, tentukan Benar atau Salah untuk setiap pernyataan berikut!",
    "teks_soal": "Cara Membuat Telur Dadar Sederhana \n        Cara Membuat Telur Dadar Sederhana  Telur dadar sangat cocok dipadukan dengan nasi hangat dan sambal. Rasanya sederhana, tetapi tetap menggugah selera. Berikut adalah cara membuat telur dadar sederhana.   Bahan-bahan:  • 1 butir telur • Sejumput garam • Sedikit merica bubuk • Minyak goreng secukupnya   Langkah-langkah:  • Pecahkan telur ke dalam mangkuk. • Tambahkan garam dan merica, lalu kocok hingga rata. • Panaskan sedikit minyak di atas wajan. • Tuang telur dan masak hingga matang kedua sisinya. • Angkat dan sajikan selagi hangat.  Telur dadar sederhana kini siap dinikmati sebagai pelengkap hidangan. Untuk variasi rasa, Anda bisa menambahkan irisan daun bawang atau keju parut sesuai dengan selera. Selamat mencoba.\n\nBerdasarkan informasi tersebut, tentukan Benar atau Salah untuk setiap pernyataan berikut!",
