    "teksSoal": "Suasana Pagi di Taman Heulang \n       Suasana pagi hari di Taman Heulang sangat sejuk. Pohon-pohon besar di sekeliling taman menghalangi sinar matahari dan membuatnya teduh. Kicau burung yang bersahutan dan semilir angin membuat orang betah duduk berlama-lama. Di tengah taman, terdapat sebuah lapangan luas dan kolam ikan. [...]. Walaupun kecil, jenis permainan yang disediakan cukup lengkap.\n\nKalimat deskripsi yang tepat untuk melengkapi bagian yang rumpang dalam teks tersebut adalah...",
