    "teksSoal": "Budiman dan Api Unggun Pramuka \n       Budiman terkejut melihat kobaran api sehingga jantungnya berdebar. Awalnya, Budiman berpikir bahwa itu adalah kebakaran hutan yang terjadi di dekat rumahnya. Namun, ternyata, kobaran api itu adalah api unggun yang dibuat anak-anak pramuka di lapangan. Budiman merasa lega setelah tahu itu hanya api unggun. Ia mendekati lapangan tempat anak-anak pramuka berkumpul. Dengan senyum, ia menyapa mereka dan ikut duduk di sekitar api.\n\nPerubahan perasaan Budiman setelah mengetahui sumber kobaran api adalah",
