    "materi": "Teks Eksplanasi Lingkungan - Kesesuaian Informasi",
    "tipe": "pg_sederhana",
    "teksSoal": "Dampak Sampah Plastik terhadap Lingkungan dan Kesehatan \n       Sampah plastik merupakan bahan yang tidak dapat diurai dengan mudah. Perlu waktu bertahun-tahun untuk dapat membuat sampah plastik terurai secara alami. Akibatnya, banyak sampah plastik yang akhirnya mencemari lingkungan kita, termasuk lautan dan sungai. Cemaran sampah plastik di sungai dan lautan pun akan berdampak pada ekosistem yang hidup di dalamnya.  Selain itu, penggunaan plastik juga memengaruhi kesehatan manusia. Plastik mengandung bahan kimia berbahaya yang dapat merusak organ dalam tubuh kita, termasuk hati, ginjal, dan paru-paru. Oleh karena itu, sebagai generasi muda, kita harus bertindak sekarang untuk mengurangi penggunaan plastik.  Upaya apa saja yang dapat kita lakukan untuk mengurangi sampah plastik? Pertama, kita bisa membawa kantong belanja yang terbuat dari kain. Kantong tersebut dapat digunakan berulang kali ketika berbelanja di pasar atau supermarket. Kedua, kita bisa mengurangi penggunaan botol plastik dengan cara membawa tempat minum atau botol minum sendiri yang dapat digunakan berulang kali. Ketiga, kita bisa menghindari penggunaan sedotan plastik dan menggantinya dengan sedotan yang terbuat dari bahan lain seperti bambu.   Sumber: dlh.bulelengkab.go.id\n\nPernyataan yang tidak sesuai dengan informasi dalam teks tersebut adalah ...",
    "teks_soal": "Dampak Sampah Plastik terhadap Lingkungan dan Kesehatan \n       Sampah plastik merupakan bahan yang tidak dapat diurai dengan mudah. Perlu waktu bertahun-tahun untuk dapat membuat sampah plastik terurai secara alami. Akibatnya, banyak sampah plastik yang akhirnya mencemari lingkungan kita, termasuk lautan dan sungai. Cemaran sampah plastik di sungai dan lautan pun akan berdampak pada ekosistem yang hidup di dalamnya.  Selain itu, penggunaan plastik juga memengaruhi kesehatan manusia. Plastik mengandung bahan kimia berbahaya yang dapat merusak organ dalam tubuh kita, termasuk hati, ginjal, dan paru-paru. Oleh karena itu, sebagai generasi muda, kita harus bertindak sekarang untuk mengurangi penggunaan plastik.  Upaya apa saja yang dapat kita lakukan untuk mengurangi sampah plastik? Pertama, kita bisa membawa kantong belanja yang terbuat dari kain. Kantong tersebut dapat digunakan berulang kali ketika berbelanja di pasar atau supermarket. Kedua, kita bisa mengurangi penggunaan botol plastik dengan cara membawa tempat minum atau botol minum sendiri yang dapat digunakan berulang kali. Ketiga, kita bisa menghindari penggunaan sedotan plastik dan menggantinya dengan sedotan yang terbuat dari bahan lain seperti bambu.   Sumber: dlh.bulelengkab.go.id\n\nPernyataan yang tidak sesuai dengan informasi dalam teks tersebut adalah ...",
