    "tipe": "pg_kompleks",
    "teksSoal": "Edo dan Sepupunya Menolong Kucing \n       Pagi hari yang cerah dimanfaatkan Edo dan sepupunya untuk bersepeda di sekitar taman kota. Mereka mengayuh sepeda dengan gembira sambil menikmati udara segar dan pepohonan rindang. Di salah satu sudut taman, mereka berhenti karena melihat seekor kucing terjebak di semak berduri. Dengan hati-hati, Edo menyingkirkan duri dan menyelamatkan kucing itu. Sepupunya lalu memberi kucing itu air minum dari botol yang mereka bawa. Setelah itu, mereka duduk di bangku taman sambil berbagi cerita. Edo berkata, \"Menolong makhluk hidup itu penting walau hanya seekor kucing.\"\n\nPeristiwa dalam teks menunjukkan tindakan Edo dan sepupunya yang mencerminkan nilai-nilai positif dalam kehidupan sehari-hari. Manakah dari pernyataan berikut yang benar-benar relevan dengan tindakan mereka?\n\n*Pilihlah jawaban yang benar! Jawaban benar lebih dari satu.*",
