    "mapel": "Bahasa Indonesia",
    "mataPelajaran": "Bahasa Indonesia",
    "materi": "Teks Argumentasi - Karakteristik Teks",
    "tipe": "pg_sederhana",
    "teksSoal": "Pencemaran Lingkungan di Kota Besar \n       Pencemaran lingkungan hampir terjadi di setiap wilayah Indonesia, terutama di kota-kota besar. Pencemaran lingkungan tersebut disebabkan oleh polusi udara dari kendaraan bermotor yang jumlahnya semakin lama semakin bertambah banyak, pembuangan limbah industri dari pabrik-pabrik yang mengandung polutan, dan ulah masyarakat sendiri yang sering membuang sampah sembarangan.  Pencemaran lingkungan tersebut dapat mengakibatkan kerugian yang cukup besar. Contohnya adalah udara menjadi kotor dan tidak sehat, menyebarnya berbagai virus dan bakteri atau terjangkitnya wabah penyakit, serta bencana banjir karena saluran-saluran air tersumbat oleh sampah.\n\nTeks tersebut termasuk jenis teks argumentasi karena.....",
    "teks_soal": "Pencemaran Lingkungan di Kota Besar \n       Pencemaran lingkungan hampir terjadi di setiap wilayah Indonesia, terutama di kota-kota besar. Pencemaran lingkungan tersebut disebabkan oleh polusi udara dari kendaraan bermotor yang jumlahnya semakin lama semakin bertambah banyak, pembuangan limbah industri dari pabrik-pabrik yang mengandung polutan, dan ulah masyarakat sendiri yang sering membuang sampah sembarangan.  Pencemaran lingkungan tersebut dapat mengakibatkan kerugian yang cukup besar. Contohnya adalah udara menjadi kotor dan tidak sehat, menyebarnya berbagai virus dan bakteri atau terjangkitnya wabah penyakit, serta bencana banjir karena saluran-saluran air tersumbat oleh sampah.\n\nTeks tersebut termasuk jenis teks argumentasi karena.....",
