    "tipe": "pg_sederhana",
    "teksSoal": "Wawancara bersama Bu Tika, Ahli Gizi: Pentingnya Sarapan Sehat \n        Wawancara bersama Bu Tika, Ahli Gizi   Wawancara ini bertujuan untuk memberikan informasi tentang pentingnya sarapan sehat bagi anak-anak usia sekolah.  Pewawancara :  Selamat pagi, Bu Tika. Apa manfaat sarapan sehat bagi anak-anak?  Bu Tika :  Selamat pagi. Sarapan sehat sangat penting karena dapat meningkatkan konsentrasi dan energi anak saat belajar di sekolah.  Pewawancara :  Makanan seperti apa yang sebaiknya dikonsumsi saat sarapan?  Bu Tika :  Anak-anak sebaiknya makan makanan yang bergizi seimbang, seperti nasi, telur, sayur, dan buah.  Pewawancara :  Bagaimana jika anak tidak terbiasa sarapan?  Bu Tika :  Orang tua bisa membiasakan anak secara bertahap, misalnya dengan memberi porsi kecil terlebih dahulu agar lambung tidak kaget.\n\nManfaat sarapan sehat bagi anak-anak usia sekolah berdasarkan teks tersebut adalah ....",
