    "tipe": "pg_sederhana",
    "teksSoal": "Mengapa Langit Berwarna Biru? \n        Mengapa Langit Berwarna Biru?   Warna biru pada langit merupakan fenomena yang menarik dan kompleks yang melibatkan interaksi antara cahaya matahari dan atmosfer bumi. Mengutip Space Place NASA, langit bisa berwarna biru karena cahaya matahari mencapai atmosfer bumi dan disebarkan ke segala arah oleh semua gas dan partikel di udara.  Meski cahaya matahari tampak putih, sebenarnya terdiri dari semua warna pelangi yaitu merah, jingga, kuning, hijau, biru, nila, dan ungu. Cahaya biru lebih banyak tersebar daripada warna lain karena bergerak dalam gelombang yang lebih pendek dan lebih kecil. Inilah sebabnya mengapa langit berwarna biru hampir sepanjang waktu.   Sumber: tempo.co\n\nBerdasarkan teks tersebut, yang menyebabkan langit berwarna biru adalah ...",
