    "tipe": "benar_salah",
    "teksSoal": "Agil Belajar Naik Sepeda Sendiri \n       \"Bu, Galih pamit main dulu ya!\" ujar Galih sambil mencium tangan ibu. \"Lho, Kak katanya hari Minggu ini mau mengajariku naik sepeda,\" sahut Agil melihat kakaknya yang hendak pergi. \"Aku bosan nih nonton televisi di rumah saja.\" \"Pergilah keluar bermain bersama teman-temanmu. Jangan di rumah terus,\" jawab Kak Galih. \"Yahhh... Teman-temanku kan sedang pergi main sepeda semua, Kak. Hanya aku yang belum bisa mengendarai sepeda,\" gerutu Agil. \"Lalu, salah siapa kamu belum bisa mengendarai sepeda?\" canda Kak Galih. \"Jangan hari ini, ya. Aku mau bermain basket dulu di lapangan. Besok saja ya, Gil!\" kata Kak Galih sambil berlari meninggalkan Agil.  Agil hanya menarik napas kecewa. Ia lalu kembali duduk menonton kartun kesukaannya. Selang beberapa menit, Agil sudah mulai gelisah dan merasa bosan. Agil membayangkan teman-temannya yang sedang asyik bermain sepeda bersama.  \"Coba aku sudah bisa naik sepeda dari dulu ya, pasti aku bisa ikut bermain bersama teman-teman,\" sesal Agil karena selama ini tidak mau berusaha keras belajar naik sepeda. Agil memutuskan untuk belajar naik sepeda sendiri. \"Pokoknya, aku harus bisa naik sepeda hari ini,\" tekad Agil dalam hati. Ia lalu mengambil sepeda dan pelindung diri yang sudah dibelikan ayah di garasi. Ia lalu memakai helm sepeda dan pelindung diri lainnya sebelum belajar mengendarai sepeda.\n\nBerdasarkan informasi tersebut, tentukan Benar atau Salah pada penggambaran tokoh dan watak sesuai dengan isi teks.",
