    "materi": "Teks Artikel Edukasi - Ringkasan Bacaan",
    "tipe": "pg_sederhana",
    "teksSoal": "Manfaat Memiara Hewan di Rumah bagi Anak \n        Manfaat Memiara Hewan di Rumah   Memiara hewan di rumah sangat bermanfaat. Hewan bisa membantu tumbuh kembang anak. Anak belajar bertanggung jawab sejak kecil. Anak belajar memberi makan hewan. Anak juga belajar menjaga kebersihan kandang.  Kegiatan merawat hewan membentuk kasih sayang. Anak jadi lebih peduli pada sesama. Anak menyadari bahwa hewan juga butuh perhatian. Sama seperti manusia, hewan perlu makan. Hewan juga butuh tempat yang nyaman.  Hewan piaraan bisa jadi teman bermain. Anak tidak merasa kesepian di rumah. Anak tunggal akan merasa lebih bahagia. Ia memiliki teman yang menyenangkan.  Hewan juga membantu anak percaya diri. Anak bangga bisa merawat hewannya. Anak bisa senang bercerita tentang piaraannya. Kebiasaan ini membuat anak lebih mudah bergaul.  Bermain dengan hewan membuat hati tenang. Anak bisa lebih relaks dan bahagia. Perasaan bahagia dapat mengurangi rasa stres. Bahkan, anak bisa jadi lebih fokus belajar.  Memiara hewan juga menyehatkan tubuh. Anak bisa lebih aktif bergerak bersama hewan. Selain itu, memiara hewan bisa memperkuat daya tahan tubuh.  Memiara hewan juga bisa mempererat hubungan keluarga. Keluarga bisa bermain bersama hewan. Kegiatan ini menumbuhkan kebersamaan. Memiara hewan memang perlu usaha. Namun, manfaatnya sangat besar untuk anak. Yuk, rawat hewan dengan kasih sayang!   Sumber: Damar Upahita/Hello Sehat (2024)\n\nManakah ringkasan yang paling tepat berdasarkan teks tersebut?",
