    "tipe": "pg_sederhana",
    "teksSoal": "Fabel: Ogi Sahabat Oyi \n        Ogi Sahabat Oyi   \"Huh! Oyi sombong!\" gumam Ogi kesal. Kini Ogi benar-benar kesal pada Oyi. Dua hari yang lalu, Ogi mengajak Oyi bermain tetapi Oyi tidak mau. Kemarin malam, Ogi mengajak Oyi latihan menyanyi, tetapi Oyi juga tidak mau. Sekarang, Ogi mengajak Oyi mencari nyamuk, lagi-lagi Oyi tidak mau. \"Mungkin Oyi sudah bosan bermain denganku!\" pikir Ogi dongkol. \"Biar saja! Aku tak mau mengajak Oyi lagi!\" Hari-hari berikutnya, Ogi bermain sendirian. Ayah Ogi heran melihatnya. \"Oyi sekarang sombong, Yah!\" jawab Ogi ketika ayahnya bertanya. \"Ia tidak mau bermain dengan Ogi lagi.\" \"Ogi tahu, kenapa Oyi tak mau diajak bermain?\" tanya Ayah lagi. \"Sudahlah, Yah! Pokoknya Oyi itu sombong!\" ujar Ogi kesal. \"Ogi, kau akan menyesal memusuhi sahabat tanpa tahu sebabnya. Seperti yang pernah Ayah alami...\" ucap ayah Ogi sedih. Ayah Ogi lalu bercerita. \"Waktu Ayah masih kecil, Ayah pernah memusuhi sahabat akrab Ayah karena ia tak mau diajak bermain. Belakangan, Ayah baru tahu. Kaki depan sahabat Ayah itu sakit hingga menjadi lumpuh. Rupanya, ia malu menceritakan penyakitnya itu kepada Ayah. Setelah mengetahui hal itu, Ayah menyesal telah memusuhi sahabat yang sedang sakit itu.\" Mendengar cerita itu, wajah Ogi menjadi pucat pasi.   Sumber: Sarah Nafisah/Bobo (2025)\n\nApa konflik utama dalam fabel tersebut?",
    "teks_soal": "Fabel: Ogi Sahabat Oyi \n        Ogi Sahabat Oyi   \"Huh! Oyi sombong!\" gumam Ogi kesal. Kini Ogi benar-benar kesal pada Oyi. Dua hari yang lalu, Ogi mengajak Oyi bermain tetapi Oyi tidak mau. Kemarin malam, Ogi mengajak Oyi latihan menyanyi, tetapi Oyi juga tidak mau. Sekarang, Ogi mengajak Oyi mencari nyamuk, lagi-lagi Oyi tidak mau. \"Mungkin Oyi sudah bosan bermain denganku!\" pikir Ogi dongkol. \"Biar saja! Aku tak mau mengajak Oyi lagi!\" Hari-hari berikutnya, Ogi bermain sendirian. Ayah Ogi heran melihatnya. \"Oyi sekarang sombong, Yah!\" jawab Ogi ketika ayahnya bertanya. \"Ia tidak mau bermain dengan Ogi lagi.\" \"Ogi tahu, kenapa Oyi tak mau diajak bermain?\" tanya Ayah lagi. \"Sudahlah, Yah! Pokoknya Oyi itu sombong!\" ujar Ogi kesal. \"Ogi, kau akan menyesal memusuhi sahabat tanpa tahu sebabnya. Seperti yang pernah Ayah alami...\" ucap ayah Ogi sedih. Ayah Ogi lalu bercerita. \"Waktu Ayah masih kecil, Ayah pernah memusuhi sahabat akrab Ayah karena ia tak mau diajak bermain. Belakangan, Ayah baru tahu. Kaki depan sahabat Ayah itu sakit hingga menjadi lumpuh. Rupanya, ia malu menceritakan penyakitnya itu kepada Ayah. Setelah mengetahui hal itu, Ayah menyesal telah memusuhi sahabat yang sedang sakit itu.\" Mendengar cerita itu, wajah Ogi menjadi pucat pasi.   Sumber: Sarah Nafisah/Bobo (2025)\n\nApa konflik utama dalam fabel tersebut?",
    "soal": "Fabel: Ogi Sahabat Oyi \n        Ogi Sahabat Oyi   \"Huh! Oyi sombong!\" gumam Ogi kesal. Kini Ogi benar-benar kesal pada Oyi. Dua hari yang lalu, Ogi mengajak Oyi bermain tetapi Oyi tidak mau. Kemarin malam, Ogi mengajak Oyi latihan menyanyi, tetapi Oyi juga tidak mau. Sekarang, Ogi mengajak Oyi mencari nyamuk, lagi-lagi Oyi tidak mau. \"Mungkin Oyi sudah bosan bermain denganku!\" pikir Ogi dongkol. \"Biar saja! Aku tak mau mengajak Oyi lagi!\" Hari-hari berikutnya, Ogi bermain sendirian. Ayah Ogi heran melihatnya. \"Oyi sekarang sombong, Yah!\" jawab Ogi ketika ayahnya bertanya. \"Ia tidak mau bermain dengan Ogi lagi.\" \"Ogi tahu, kenapa Oyi tak mau diajak bermain?\" tanya Ayah lagi. \"Sudahlah, Yah! Pokoknya Oyi itu sombong!\" ujar Ogi kesal. \"Ogi, kau akan menyesal memusuhi sahabat tanpa tahu sebabnya. Seperti yang pernah Ayah alami...\" ucap ayah Ogi sedih. Ayah Ogi lalu bercerita. \"Waktu Ayah masih kecil, Ayah pernah memusuhi sahabat akrab Ayah karena ia tak mau diajak bermain. Belakangan, Ayah baru tahu. Kaki depan sahabat Ayah itu sakit hingga menjadi lumpuh. Rupanya, ia malu menceritakan penyakitnya itu kepada Ayah. Setelah mengetahui hal itu, Ayah menyesal telah memusuhi sahabat yang sedang sakit itu.\" Mendengar cerita itu, wajah Ogi menjadi pucat pasi.   Sumber: Sarah Nafisah/Bobo (2025)\n\nApa konflik utama dalam fabel tersebut?",
