    "mapel": "Bahasa Indonesia",
    "mataPelajaran": "Bahasa Indonesia",
    "materi": "Teks Sejarah Kebangsaan - Kongres Pemuda I dan Persatuan Bangsa",
    "tipe": "pg_sederhana",
    "teksSoal": "Kongres Pemuda I dan Persatuan Bangsa \n        Kongres Pemuda I dan Persatuan Bangsa   Kongres Pemuda I terjadi pada 1926. Kongres diadakan pada 30 April - 2 Mei di Jakarta. Banyak organisasi pemuda ikut serta. Mereka datang dari berbagai daerah di Indonesia. Tujuan utama kongres adalah persatuan. Para pemuda ingin Indonesia bersatu.  Sebelum kongres, organisasi sudah banyak. Contohnya Jong Java dan Jong Sumatranen Bond. Ada juga Jong Celebes dan Jong Ambon. Mereka bergerak sesuai daerah masing-masing. Namun, muncul kesadaran untuk bersatu. Satiman dari Tri Koro Dharmo memulai. Ia membayangkan organisasi pemuda bersatu. Perwakilan organisasi lalu berkumpul. Mereka membentuk panitia Kongres Pemuda 1. Panitia kongres diketuai oleh Mohammad Tabrani.  Tujuan kongres ada beberapa capaian. Pertama, menyatukan organisasi pemuda Indonesia. Kedua, memperkuat semangat kebangsaan. Ketiga, membentuk dasar kemerdekaan Indonesia.  Kongres Pemuda I menghasilkan keputusan penting. Ada beberapa keputusan hasil Kongres Pemuda I. Pertama, kemerdekaan Indonesia menjadi cita-cita para pemuda. Kedua, perserikatan pemuda harus bersatu padu. Ketiga, seluruh pemuda menginginkan Indonesia merdeka. Keempat, organisasi pemuda mewadahi semangat persatuan. Kongres Pemuda I menjadi langkah awal. Peristiwa ini menginspirasi generasi berikutnya. Persatuan bangsa menjadi harapan semua pemuda.   Sumber: Muhtar/UICI (2024)\n\nBagaimana pelaksanaan Kongres Pemuda I sesuai isi teks?",
    "teks_soal": "Kongres Pemuda I dan Persatuan Bangsa \n        Kongres Pemuda I dan Persatuan Bangsa   Kongres Pemuda I terjadi pada 1926. Kongres diadakan pada 30 April - 2 Mei di Jakarta. Banyak organisasi pemuda ikut serta. Mereka datang dari berbagai daerah di Indonesia. Tujuan utama kongres adalah persatuan. Para pemuda ingin Indonesia bersatu.  Sebelum kongres, organisasi sudah banyak. Contohnya Jong Java dan Jong Sumatranen Bond. Ada juga Jong Celebes dan Jong Ambon. Mereka bergerak sesuai daerah masing-masing. Namun, muncul kesadaran untuk bersatu. Satiman dari Tri Koro Dharmo memulai. Ia membayangkan organisasi pemuda bersatu. Perwakilan organisasi lalu berkumpul. Mereka membentuk panitia Kongres Pemuda 1. Panitia kongres diketuai oleh Mohammad Tabrani.  Tujuan kongres ada beberapa capaian. Pertama, menyatukan organisasi pemuda Indonesia. Kedua, memperkuat semangat kebangsaan. Ketiga, membentuk dasar kemerdekaan Indonesia.  Kongres Pemuda I menghasilkan keputusan penting. Ada beberapa keputusan hasil Kongres Pemuda I. Pertama, kemerdekaan Indonesia menjadi cita-cita para pemuda. Kedua, perserikatan pemuda harus bersatu padu. Ketiga, seluruh pemuda menginginkan Indonesia merdeka. Keempat, organisasi pemuda mewadahi semangat persatuan. Kongres Pemuda I menjadi langkah awal. Peristiwa ini menginspirasi generasi berikutnya. Persatuan bangsa menjadi harapan semua pemuda.   Sumber: Muhtar/UICI (2024)\n\nBagaimana pelaksanaan Kongres Pemuda I sesuai isi teks?",
    "soal": "Kongres Pemuda I dan Persatuan Bangsa \n        Kongres Pemuda I dan Persatuan Bangsa   Kongres Pemuda I terjadi pada 1926. Kongres diadakan pada 30 April - 2 Mei di Jakarta. Banyak organisasi pemuda ikut serta. Mereka datang dari berbagai daerah di Indonesia. Tujuan utama kongres adalah persatuan. Para pemuda ingin Indonesia bersatu.  Sebelum kongres, organisasi sudah banyak. Contohnya Jong Java dan Jong Sumatranen Bond. Ada juga Jong Celebes dan Jong Ambon. Mereka bergerak sesuai daerah masing-masing. Namun, muncul kesadaran untuk bersatu. Satiman dari Tri Koro Dharmo memulai. Ia membayangkan organisasi pemuda bersatu. Perwakilan organisasi lalu berkumpul. Mereka membentuk panitia Kongres Pemuda 1. Panitia kongres diketuai oleh Mohammad Tabrani.  Tujuan kongres ada beberapa capaian. Pertama, menyatukan organisasi pemuda Indonesia. Kedua, memperkuat semangat kebangsaan. Ketiga, membentuk dasar kemerdekaan Indonesia.  Kongres Pemuda I menghasilkan keputusan penting. Ada beberapa keputusan hasil Kongres Pemuda I. Pertama, kemerdekaan Indonesia menjadi cita-cita para pemuda. Kedua, perserikatan pemuda harus bersatu padu. Ketiga, seluruh pemuda menginginkan Indonesia merdeka. Keempat, organisasi pemuda mewadahi semangat persatuan. Kongres Pemuda I menjadi langkah awal. Peristiwa ini menginspirasi generasi berikutnya. Persatuan bangsa menjadi harapan semua pemuda.   Sumber: Muhtar/UICI (2024)\n\nBagaimana pelaksanaan Kongres Pemuda I sesuai isi teks?",
